export interface PhotoPilePhoto {
  /** Stable key for this photo. */
  id: string
  src: string
  alt: string
  /** Horizontal offset from the center, in CSS pixels. */
  x?: number
  /** Vertical offset from the center, in CSS pixels. */
  y?: number
  /** Resting rotation in degrees. */
  rotation?: number
